/**
 * Billing report formatter. Renders records into the line format used by the
 * finance export.
 */

const HEADER = 'id|name|amount|discount|created'
const UTC_PLUS_EIGHT_MS = 8 * 60 * 60 * 1000

function formatCents(value) {
  return ((value ?? 0) / 100).toFixed(2)
}

function formatCreated(createdAt) {
  return new Date((createdAt ?? 0) + UTC_PLUS_EIGHT_MS)
    .toISOString()
    .replace('Z', '+08:00')
}

export function formatReport(records) {
  const lines = [HEADER]

  for (const record of records) {
    const name = typeof record.name === 'string' ? record.name : ''
    const amount = formatCents(record.amount)
    const discount = formatCents(record.discount)
    const created = formatCreated(record.createdAt)
    lines.push(`${record.id}|${name}|${amount}|${discount}|${created}`)
  }

  return lines
}

